const e={back:"Back",continue:"Continue",step_of:"{current} of {total}",welcome:{skip_all:"Skip setup, I know my way around",title:"Welcome",lede:"First a short look at what {name} is and how it works. Then we set it up right here in the app: an API key, a subscription for your agents and your wake word.",language:"Language",lang_en:"English",lang_de:"Deutsch",lang_es:"Español",start:"Let's start"},how:{title:"How {name} works",lede:"Your pet walks you through the app and explains how {name} works.",next:"Next",prev:"Back",skip:"Skip",finish:"Let's set it up",beat_of:"Explanation {current} of {total}",beats:{hello:"Hi, I'm {pet}! Before we set anything up, let me show you how {name} works. It's quick, and you'll see the real app while I explain.",talk:"Everything starts here. You talk to one assistant: {name}. Type here, or press the round button and just speak. You never pick a tool or a model yourself; {name} decides what's needed.",brain:"To think, {name} needs a brain: an AI model from OpenAI, Google, Anthropic or another provider, or one on your own computer. One key is enough, and we'll add it together in a moment.",tools:"Then {name} needs hands. It can use your computer and browser on its own, plus every app you connect here: mail, calendar, notes, smart home. When you ask for something, it picks the right tool itself.",agents:"Big jobs like research, a report or a website go to agents. They're {name}'s team: {name} hands them the work and keeps talking with you, and a reviewer checks the result before it reaches you.",ide:"Coding agents such as Claude Code and Codex work here, in real terminals on your own projects. Type to them directly, or let {name} steer them by voice.",results:"Whatever comes out, like pages, reports or images, lands in Artifacts. Short answers come straight back in the chat or spoken aloud.",memory:"{name} also remembers. What you tell it goes into its notes and your profile, stored on your computer, so you never have to repeat yourself.",safety:"And you stay in control. Harmless things just happen. Anything that sends, deletes or costs money waits for your yes first.",done:"That's the whole idea: you talk, {name} thinks, uses tools, brings in agents and hands you the result. Stuck later? Just ask {name}. Now let's give it a brain."}},keys:{next_hint:"Next: connect the subscriptions you already pay for, so your agents can work.",no_key:"No key yet? A free local model works too (Settings → Local models), or skip and add one later. Without any, chat and voice stay off.",live_missing:"Chat works. Live voice needs an OpenAI or Gemini key; until then {name} speaks the classic way, a little slower.",live_ready:"Live voice is on: talk, and {name} answers right away.",title:"Add one API key",lede:"This is the API Keys page. Paste one key into a provider card and save it; that is all {name} needs to think and talk. An OpenAI (ChatGPT) or Google Gemini key also gives you live voice.",waiting:"Waiting for a key…",connecting:"Switching everything on…",connected:"Connected: {provider}.",present:"A key is saved. You can continue.",partial:"Some parts did not switch ({parts}). You can fix them later on this page.",security:"Keys go into your system's keychain and only ever to the provider you picked.",later:"I'll add a key later"},subscriptions:{title:"Connect a subscription for your agents",lede:"This is the Agents tab. Agents run best on a subscription you already pay for; we recommend Claude (Pro or Max) or ChatGPT (Codex). Click Connect on its row, and your browser opens once.",waiting:"No subscription connected yet…",connected:"Connected: {names}.",why:"A subscription is a flat monthly price. Without one, agents use your API key and each job is billed per use.",later:"I'll connect one later"},permissions:{title:"Allow access on this Mac",lede:"These are the Mac permissions. Allow the ones you want; each row updates by itself.",note:"You can come back to them anytime in Settings. The restart at the end applies them."},voice:{title:"Choose your wake word",lede:`Type your word after "Hey" here and save it. The word also becomes the assistant's name. No wake word? The Call shortcut works anytime.`,on:'"{phrase}" is on. Say it anytime.',off:"No wake word yet. The Call shortcut works meanwhile.",later:"Skip, I'll use the Call shortcut"},ready:{title:"All set",lede:"Here is what is set up. Next, a short tour shows you around the app.",row_brain:"Brain",row_agents:"Agents",row_voice:"Activation",no_subscription:"No subscription",no_key:"No key yet",shortcut:"Call shortcut",autostart:"Start at login",no_key_note:"Without a key, chat and voice stay off until you add one on the API Keys page.",preview_note:"This is a replay, so nothing restarts.",restart_note:"When the tour ends, the app restarts once (about ten seconds) to switch everything on.",start:"Show me around"}},t={label:"App tour",next:"Next",finish:"Finish",skip:"Skip tour",step_of:"{current} of {total}",replay_title:"Do the onboarding again",replay_body:"Explains again how {name} works, walks you through setup (API keys, agent subscriptions, wake word), then the short tour of the app. Nothing restarts.",replay:"Replay",steps:{voice:"This is how you talk to {name}. Click the bar, say your wake word or press your Call keys, then just speak. The wave shows who is talking.",new_chat:"Rather type? Start a new chat here, as text or voice. Every conversation lands under Recent chats.",agents_world:"This is the Verse, your agents at work. Click one to chat with it or hand it a job. Next brings you back.",voice_hub:"Voice holds dictation into any app, your own word list and spoken shortcuts.",settings:"Settings, API keys, costs and your profile live here. You can replay this tour anytime from Settings → App.",done:"That's the tour. Talk to {name} whenever you like, and if you're ever stuck, just ask {name}. Settings → App runs the onboarding again."}},o={title:"First steps",progress:"{done}/{total}",collapse:"Minimise",close:"Close",quest_of:"Step {current} of {total}",how_label:"How it works:",waiting:"Sent. Watch the chat: {name} is on it.",next:"Next step",finish:"Finish",skip:"Skip this one",try:{send:"Send it for me",voice:"Open voice mode",open:"Take me there"},show:{memory:"Open Notes",artifact:"Open Artifacts",agent:"Watch in Agents"},replay_title:"First steps with {name}",replay:"Start",replay_body:"Ten small, real things to try with {name}: talk, use tools, remember, build, hand off to agents. Each one is explained after it happened.",finished:{title:"You've got the basics!",body:"You completed {done} of {total} first steps. From now on, just talk to {name}: it decides whether to answer, use a tool or bring in an agent. Stuck? Ask {name}.",close:"Close"},quests:{wake:{title:"Wake {name} up",ask:'Say your wake word out loud, for example "Hey {name}". Or open voice mode and press the round button in the chat bar. Then just ask anything.',explain:"{name} is listening. That's all it takes: wake it up and talk like you would to a person.",how:"Your wake word is recognised right here on your computer. Only after it does your speech go to the brain, and the answer comes back as a voice."},ask:{title:"Ask your first question",ask:"Type or say a question. Try this one:",prompt:"What can you do for me? Give me three examples from my everyday life.",explain:"That was the simplest path: your words went to the brain, and it answered directly.",how:"The brain is the AI model you connected. Plain questions need no tools, so the answer comes in seconds. Every chat is saved under Recent chats."},tool:{title:"Let it use a tool",ask:"Now ask for something that needs its hands, not just its head:",prompt:"Open wikipedia.org in my browser.",explain:"This time the brain did not just answer: it used a tool to act on your computer.",how:"Tools are {name}'s hands. The brain picks one, the safety check approves it, and it runs. Under each reply you can open the steps and see every tool it used."},screen:{title:"Let it look at your screen",ask:"{name} can see your screen, but only when you ask. Try:",prompt:"What's on my screen right now? Describe it briefly.",explain:"{name} took one look at your screen and described it.",how:"A screen look is a single snapshot, taken only when a request needs it. It goes to the brain like a photo. Nothing records your screen in the background."},memory:{title:"Teach it something",ask:"Tell {name} something worth keeping:",prompt:"Remember that my favourite colour is blue and that I prefer short answers.",explain:"{name} saved this to its memory and will use it from now on.",how:"Facts land in your Wiki and profile, stored on your computer. Before answering, {name} looks up what it knows about you. You can read and edit every note in Notes."},artifact:{title:"Have it make something",ask:'{name} can build finished things: pages, overviews, small tools. Say "artifact" to ask for one:',prompt:"Create an artifact: a one-page overview of the planets in our solar system, with one fun fact each.",explain:"{name} started building the page. When it is ready, it appears in Artifacts.",how:"An artifact is a bigger piece of work, so {name} hands it to a worker on a strong model. It builds one self-contained page, and Artifacts keeps it for you to open again later."},agent:{title:"Hand a big job to an agent",ask:"For longer work, {name} brings in an agent. You can keep talking while it works:",prompt:"Research the three best budget laptops right now and write me a short comparison.",explain:"{name} handed the job to an agent. It works in the background; the result comes back to your chat.",how:"{name} stays your single contact. It plans the job and starts an agent, and a reviewer checks the result before it reaches you. You can watch the progress in Agents."},team:{title:"Meet your team",ask:"Agents are helpers with their own role. Open the Agents area to meet them.",explain:"This is where your agents live and work.",how:"Create your own agent with its own role, model and instructions, for example a researcher or a writer. Click an agent to chat with it or give it a job. {name} can also hand work to it for you."},plugin:{title:"Connect an app",ask:"Plugins connect {name} to the apps you use: email, calendar, notes, smart home and more.",explain:"Here you connect your apps. Pick one you use every day and click Connect; your browser opens once to sign in.",how:`Each connected app becomes a new tool for {name}. Afterwards just ask, for example "What's on my calendar tomorrow?". Anything that sends or changes something still asks you first.`},ide:{title:"Let agents write code",ask:"The Agentic IDE runs coding agents such as Claude Code and Codex in real terminals, on your own projects.",explain:"This is the Agentic IDE. Open a project folder and start a coding agent in a pane.",how:"Each pane is a real terminal with its own agent. Talk to them by typing, or by voice through {name}. Several can work side by side on the same project."}}},a={first_run:e,app_tour:t,first_steps:o};export{t as app_tour,a as default,e as first_run,o as first_steps};
